begin;
create extension if not exists pgtap with schema extensions;
set local search_path to public, extensions;
select plan(9);
insert into auth.users(id,email) values ('10000000-0000-0000-0000-000000000001','trade-a@example.test'),('10000000-0000-0000-0000-000000000002','trade-b@example.test');
insert into public.businesses(id,name) values ('20000000-0000-0000-0000-000000000001','Trade A'),('20000000-0000-0000-0000-000000000002','Trade B');
insert into public.business_members(business_id,user_id,role) values ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','owner'),('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000002','owner');
insert into public.customers(id,business_id,name) values ('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','A'),('30000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','B');
insert into public.jobs(id,business_id,customer_id,title) values ('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','A'),('40000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000002','B');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.job_trade_worksheets values ('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','{}')$$,'owner saves own worksheet');
select throws_ok($$insert into public.job_trade_worksheets values ('40000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001','{}')$$,'42501',null,'cannot attach worksheet to foreign job');
select throws_ok($$update public.job_trade_worksheets set business_id='20000000-0000-0000-0000-000000000002'$$,'42501',null,'cannot move worksheet to foreign business');
select lives_ok($$insert into public.trade_scope_templates values ('20000000-0000-0000-0000-000000000001','Standard','{}')$$,'owner saves template');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.job_trade_worksheets),0,'other owner cannot read worksheet');
select is((select count(*)::int from public.trade_scope_templates),0,'other owner cannot read template');
select throws_ok($$insert into public.trade_scope_templates values ('20000000-0000-0000-0000-000000000001','Intrusion','{}')$$,'42501',null,'other owner cannot write template');
select lives_ok($$update public.job_trade_worksheets set body='{"changed":true}'$$,'foreign update touches no visible rows');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select body::text from public.job_trade_worksheets),'{}','foreign update did not change owner worksheet');
reset role;
select * from finish();
rollback;
